definition:
\foreach \c [count=\i from 0] in {black, black!70, blue!70!black, red!70!black,
                                   green!50!black, gray!50, blue!30, yellow!60,
                                   white, orange}{
  \fill[\c] (\i*1.15, 2.2) rectangle (\i*1.15+1.1, 4.6);
  \node[font=\tiny, text=white]  at (\i*1.15+0.55, 4.2) {Wht};
  \node[font=\tiny, text=black]  at (\i*1.15+0.55, 3.4) {Blk};
  \node[font=\tiny]              at (\i*1.15+0.55, 2.6) {Def};
  \node[font=\tiny, rotate=90, anchor=east] at (\i*1.15+0.55, 2.1) {\c};
}
\node[font=\small, left] at (-0.2,3.4) {fills};
% labelled nodes whose own fill carries the label
\foreach \c/\l [count=\i from 0] in {black/N1, blue!80!black/N2, red!85!black/N3,
                                      gray!80/N4, green!25/N5, white/N6}{
  \node[draw, fill=\c, minimum size=1.4cm, font=\small] at (\i*1.9+0.7, -0.8) {\l};
}
\node[font=\small, left] at (-0.2,-0.8) {default-ink labels};
\foreach \c/\l [count=\i from 0] in {black/M1, blue!80!black/M2, red!85!black/M3,
                                      gray!80/M4, green!25/M5, white/M6}{
  \node[draw, fill=\c, text=white, minimum size=1.4cm, font=\small] at (\i*1.9+0.7, -2.8) {\l};
}
\node[font=\small, left] at (-0.2,-2.8) {white-ink labels};
